:root{--bg:#090b1b;--panel:#10142a;--panel2:#151a34;--gold:#ffcf72;--gold2:#f8a84b;--mint:#66f3d0;--muted:#858ba7;--white:#f8f6ff;--pink:#ff77bd}
*{box-sizing:border-box}html{min-height:100%;background:var(--bg)}body{margin:0;min-height:100vh;color:var(--white);font-family:'DM Sans',sans-serif;background:radial-gradient(ellipse at 50% 34%,#181737 0%,#0d1023 34%,#090b1b 74%);overflow-x:hidden}.ambient{position:fixed;z-index:0;pointer-events:none;border-radius:50%;filter:blur(100px);opacity:.2}.ambient-one{width:360px;height:360px;background:#a536b9;top:230px;left:-190px}.ambient-two{width:400px;height:400px;background:#1a9fbd;top:470px;right:-260px}.app-shell{position:relative;z-index:1;max-width:1130px;margin:auto;padding:0 36px}.topbar{height:82px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(193,190,255,.1)}.brand{display:flex;align-items:center;gap:10px;text-decoration:none;color:white}.brand-mark{width:32px;height:32px;border:1px solid rgba(255,207,114,.62);border-radius:10px;display:grid;place-items:center;transform:rotate(-8deg);background:linear-gradient(145deg,rgba(255,207,114,.16),rgba(255,207,114,.02));box-shadow:0 0 18px #ffcf7233}.brand-mark span{color:var(--gold);font-size:20px;transform:rotate(8deg)}.brand-name{font-family:Outfit,sans-serif;font-weight:800;letter-spacing:1.2px;font-size:15px}.brand-name span{color:#c6c1df;margin-left:4px;font-weight:600}.top-note{font-size:10px;letter-spacing:1.6px;color:#9298b6;font-weight:700;display:flex;align-items:center;gap:9px}.top-note i{color:#3f4561;font-style:normal}.live-dot,.status-pip{width:6px;height:6px;display:inline-block;background:var(--mint);border-radius:50%;box-shadow:0 0 10px var(--mint)}.wallet{display:flex;align-items:center;gap:10px;padding:8px 13px;border:1px solid rgba(255,207,114,.2);background:linear-gradient(110deg,rgba(255,207,114,.07),rgba(255,207,114,.02));border-radius:12px;min-width:145px}.wallet-icon{font-size:22px;color:var(--gold)}.wallet div{display:flex;flex-direction:column;gap:1px}.wallet small{font-size:8px;letter-spacing:1.4px;color:#9298b6;font-weight:700}.wallet strong{font-family:Outfit,sans-serif;font-size:17px;line-height:1.1;letter-spacing:.5px}.wallet-coin{margin-left:auto;color:var(--gold);font-size:13px}.intro{text-align:center;padding:27px 0 15px}.eyebrow,.modal-eyebrow{display:flex;align-items:center;justify-content:center;gap:11px;color:var(--mint);font-size:9px;letter-spacing:2.7px;font-weight:800}.eyebrow-line{width:24px;height:1px;background:linear-gradient(90deg,transparent,var(--mint))}.eyebrow-line:last-child{transform:rotate(180deg)}h1{font-family:Outfit,sans-serif;font-size:38px;line-height:1.05;margin:9px 0 5px;letter-spacing:-.7px;font-weight:700}h1 span{color:var(--gold);text-shadow:0 0 30px #ffc56840}.intro p{font-size:12px;color:#a6abc3;margin:0}.intro p b{color:#d7d9e7;font-weight:600}
.machine-wrap{max-width:760px;margin:0 auto;position:relative;filter:drop-shadow(0 25px 48px #02030c88)}.machine-topline{height:30px;display:flex;align-items:center;justify-content:space-between;padding:0 12px}.jackpot-label{font-family:Outfit,sans-serif;font-weight:800;color:var(--gold);letter-spacing:1.6px;font-size:10px;text-shadow:0 0 10px #ffcf7240}.jackpot-star{font-size:12px;padding:0 6px}.machine-status{display:flex;gap:8px;align-items:center;color:#8f95b2;font-size:8px;font-weight:800;letter-spacing:1.4px}.status-pip{width:5px;height:5px}.cabinet{position:relative;padding:11px;border-radius:20px;background:linear-gradient(135deg,#594167 0%,#f0b86f 8%,#613d67 12%,#17182d 18%,#28233e 50%,#121326 87%,#dfa866 94%,#4c3158 100%);box-shadow:inset 0 1px 2px #fff8,0 0 0 1px #ffcf722c,0 0 50px #c464ed17}.cabinet:before{content:'';position:absolute;inset:5px;border-radius:16px;border:1px solid #ffdfa344;pointer-events:none}.cabinet-inner{position:relative;border-radius:13px;background:linear-gradient(160deg,#17172f,#101326 60%,#17142c);padding:10px 20px 11px;overflow:hidden}.cabinet-inner:before{content:'';position:absolute;inset:0;background:radial-gradient(ellipse at 50% -10%,#a65eb021,transparent 58%);pointer-events:none}.marquee{height:39px;display:flex;align-items:center;justify-content:center;gap:19px;margin-bottom:9px;position:relative}.marquee-title{font-family:Outfit,sans-serif;font-size:20px;letter-spacing:5px;font-weight:800;color:#fff4d6;text-shadow:0 0 13px #ffc66088,0 2px 0 #8b5a3b}.marquee-title b{color:var(--gold);font-weight:900}.marquee-star{color:var(--gold);font-size:17px;text-shadow:0 0 12px var(--gold)}
.reel-frame{position:relative;border-radius:11px;padding:8px;background:linear-gradient(180deg,#0b0c1a,#24223c 50%,#0a0c1b);border:1px solid #6c5a7a;box-shadow:inset 0 3px 12px #02030ba8,0 0 0 3px #ffcf7210,0 0 25px #a344d51a;overflow:hidden}.reel-glow{position:absolute;z-index:1;inset:7px;pointer-events:none;border-radius:7px;background:linear-gradient(90deg,#090b1b99,transparent 8%,transparent 92%,#090b1b99)}.reels{display:grid;grid-template-columns:repeat(5,1fr);gap:7px;position:relative;z-index:0}.reel{height:192px;display:grid;grid-template-rows:repeat(3,1fr);overflow:hidden;background:linear-gradient(90deg,#e6dbff08,transparent 24%,#fff5ff0a 50%,transparent 78%,#c4b5ff0c),linear-gradient(180deg,#11152b,#1d203b 50%,#11152b);border-radius:6px;border:1px solid #ffffff0f;box-shadow:inset 0 0 18px #02030b99;position:relative}.reel:after{content:'';position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,#0a0c1d9e,transparent 24%,transparent 76%,#0a0c1d9e)}.symbol{display:grid;place-items:center;font-size:39px;line-height:1;filter:drop-shadow(0 4px 5px #02030bbb);border-bottom:1px solid #ffffff08;user-select:none;position:relative}.symbol.win-symbol{animation:winPulse .8s ease-in-out infinite alternate;z-index:2;filter:drop-shadow(0 0 10px #ffcf72)}@keyframes winPulse{from{transform:scale(1);text-shadow:0 0 3px #ffcf72}to{transform:scale(1.13);text-shadow:0 0 22px #ffcf72}}.reel.spinning .symbol{animation:reelBlur .1s linear infinite;filter:blur(2px);opacity:.78}@keyframes reelBlur{to{transform:translateY(3px)}}.payline-indicator{position:absolute;z-index:2;top:50%;height:2px;width:10px;background:var(--gold);box-shadow:0 0 9px var(--gold);opacity:.85}.payline-indicator.left{left:0}.payline-indicator.right{right:0}.machine-foot{height:24px;display:flex;align-items:center;justify-content:center;gap:12px;color:#747b99;letter-spacing:2px;font-size:8px;font-weight:800}.machine-foot i{width:3px;height:3px;border-radius:50%;background:#c2a8db;box-shadow:0 0 6px #c2a8db}
.controls{position:relative;display:grid;grid-template-columns:1fr 1.2fr 1fr;align-items:center;min-height:94px;padding:8px 12px 4px;border-top:1px solid #ffffff0b}.control-label{color:#8f95b2;font-weight:800;letter-spacing:1.6px;font-size:8px}.bet-control,.win-display{display:flex;flex-direction:column;align-items:center;gap:4px}.bet-stepper{display:flex;align-items:center;gap:13px}.bet-stepper button{border:1px solid #494460;background:#202039;color:#ece9fb;border-radius:7px;width:25px;height:25px;font-size:17px;line-height:1;cursor:pointer;transition:.15s}.bet-stepper button:hover{border-color:var(--gold);color:var(--gold);background:#29233c}.bet-stepper strong{font-family:Outfit,sans-serif;font-size:19px;min-width:31px;text-align:center}.bet-caption,.win-caption{color:#6e7490;font-size:7px;letter-spacing:1.1px;font-weight:700}.spin-zone{display:flex;align-items:center;justify-content:center;gap:11px}.spin-button{position:relative;overflow:hidden;width:112px;height:74px;border:1px solid #fff1bb;border-radius:13px;background:linear-gradient(145deg,#ffe39a 0%,#ffc760 35%,#f39940 100%);color:#4a2536;box-shadow:0 5px 0 #a85b39,0 8px 20px #f6a94740,inset 0 1px 2px #fff9;display:flex;flex-direction:column;align-items:center;justify-content:center;cursor:pointer;transition:transform .12s,filter .15s}.spin-button:hover{filter:brightness(1.12);transform:translateY(-2px);box-shadow:0 7px 0 #a85b39,0 10px 25px #f6a94755}.spin-button:active{transform:translateY(3px);box-shadow:0 2px 0 #a85b39}.spin-button:disabled{opacity:.55;cursor:wait;filter:saturate(.6);transform:none}.spin-button>span:not(.spin-shine){position:relative;z-index:1}.spin-icon{font-size:23px;line-height:20px;font-weight:700}.spin-button>span:nth-child(3){font-family:Outfit,sans-serif;font-size:16px;font-weight:900;letter-spacing:2px}.spin-button small{position:relative;z-index:1;font-size:6px;letter-spacing:1.5px;font-weight:900;opacity:.65}.spin-shine{position:absolute;top:-40%;left:-90%;width:45%;height:180%;background:linear-gradient(90deg,transparent,#fff8,transparent);transform:rotate(22deg);animation:shine 4s ease-in-out infinite}@keyframes shine{0%,55%{left:-90%}80%,100%{left:150%}}.auto-button{height:40px;padding:0 10px;border:1px solid #48405f;background:#201e38;color:#c0bdd4;border-radius:9px;font-family:Outfit,sans-serif;font-size:9px;font-weight:800;letter-spacing:1px;cursor:pointer;display:flex;align-items:center;gap:5px;transition:.15s}.auto-button:hover{border-color:#bd8dec;color:#fff}.auto-button.active{border-color:var(--mint);color:var(--mint);box-shadow:0 0 14px #66f3d022}.auto-icon{font-size:15px}.auto-count{font-family:'DM Sans',sans-serif;font-size:8px;border-radius:50%;background:#ffffff12;width:17px;height:17px;display:grid;place-items:center}.win-display strong{font-family:Outfit,sans-serif;color:var(--gold);font-size:24px;line-height:1;text-shadow:0 0 15px #ffcf7240}.win-display.is-win strong{animation:winText .7s ease-in-out infinite alternate}@keyframes winText{to{transform:scale(1.1);text-shadow:0 0 22px var(--gold)}}.cabinet-bottom{height:25px;display:flex;justify-content:center;align-items:center;gap:10px;font-size:7px;color:#696f8a;letter-spacing:2px;font-weight:800}.bottom-bulb{color:#f4bd6d;text-shadow:0 0 8px #f4bd6d;font-size:10px}.cabinet-base{height:10px;width:90%;margin:auto;background:linear-gradient(90deg,transparent,#b9885633 9%,#1d1b32 20%,#2d2440 50%,#1d1b32 80%,#b9885633 91%,transparent);border-radius:0 0 50% 50%}
.below-machine{max-width:760px;margin:5px auto 0}.game-message{height:30px;display:flex;justify-content:center;align-items:center;gap:12px;color:#b1abc6;font-size:11px;letter-spacing:.15px}.message-sparkle{color:var(--pink);font-size:14px}.game-message.win-message{color:var(--gold)}.info-row{display:grid;grid-template-columns:1.15fr 1fr;gap:12px;margin-top:8px}.info-card{min-height:69px;border:1px solid #ffffff11;background:linear-gradient(120deg,#15182fdd,#111428dd);border-radius:11px;padding:12px 15px;display:flex;align-items:center;gap:12px;text-align:left;color:inherit}.card-icon{flex:0 0 31px;width:31px;height:31px;display:grid;place-items:center;border-radius:9px;background:#64eacc12;color:var(--mint);font-size:20px}.info-card h3{margin:0 0 4px;font-family:Outfit,sans-serif;letter-spacing:1.2px;font-size:9px;color:#e5e3f0}.info-card p{margin:0;color:#969bb4;font-size:9px;line-height:1.45}.info-card p b{color:#f0d48d}.paytable-card{width:100%;cursor:pointer;transition:.2s}.paytable-card:hover{border-color:#f6cb7044;transform:translateY(-1px)}.paytable-card .card-icon{background:#ffcf7212;color:var(--gold)}.paytable-card h3{color:var(--gold)}.card-arrow{margin-left:auto;color:#f5c46b;font-size:18px}.responsible-note{margin:14px 0 16px;text-align:center;color:#737991;font-size:7px;font-weight:700;letter-spacing:1.2px}.responsible-note span{color:var(--mint);font-size:10px;vertical-align:-1px;margin-right:4px}footer{height:41px;border-top:1px solid #ffffff0b;display:flex;align-items:center;justify-content:space-between;color:#565c76;font-size:7px;letter-spacing:1.5px;font-weight:800}footer b{color:var(--gold);font-size:10px;margin-left:4px}

