.modal-backdrop{position:fixed;z-index:10;inset:0;background:#050611c9;backdrop-filter:blur(8px);display:grid;place-items:center;padding:20px;opacity:0;visibility:hidden;transition:.2s}.modal-backdrop.open{opacity:1;visibility:visible}.modal{position:relative;width:min(460px,100%);padding:29px;border:1px solid #ffcf723f;border-radius:18px;background:radial-gradient(ellipse at 50% 0%,#332441,#17182d 55%,#111326);box-shadow:0 24px 80px #000b,0 0 45px #bf6dff18;transform:translateY(12px);transition:.25s}.open .modal{transform:translateY(0)}.modal-close{position:absolute;right:15px;top:13px;border:0;background:transparent;color:#a6a4ba;font-size:26px;cursor:pointer}.modal-eyebrow{font-size:8px;letter-spacing:1.9px;color:var(--mint)}.modal h2{font-family:Outfit,sans-serif;font-size:29px;text-align:center;margin:8px 0 5px}.modal h2 span{color:var(--gold)}.modal-intro{text-align:center;font-size:10px;color:#a7abc1;margin:0 auto 17px;max-width:320px;line-height:1.5}.paytable-list{display:flex;flex-direction:column;gap:6px}.paytable-row{display:grid;grid-template-columns:37px 1fr auto;align-items:center;gap:8px;padding:8px 10px;border:1px solid #ffffff0b;background:#ffffff05;border-radius:9px}.pay-symbol{font-size:24px;text-align:center}.paytable-row strong{font-size:11px;color:#e8e5f4}.payout{font-family:Outfit,sans-serif;color:var(--gold);font-size:15px;font-weight:800;text-align:right}.payout small{display:block;color:#9da1b7;font-family:'DM Sans',sans-serif;font-size:8px;font-weight:600}.bonus-note{display:flex;align-items:center;gap:9px;background:#64eacc0c;border:1px solid #64eacc22;border-radius:9px;padding:9px 11px;margin:12px 0 14px}.bonus-note>span{font-size:20px}.bonus-note p{font-size:9px;color:#aeb6c5;line-height:1.45;margin:0}.bonus-note b{color:var(--mint)}.modal-done{width:100%;height:39px;border:0;border-radius:8px;background:linear-gradient(100deg,#ffdc88,#f5ab50);color:#47293a;font-family:Outfit,sans-serif;font-size:11px;font-weight:900;letter-spacing:1.6px;cursor:pointer}.modal-done span{margin-left:4px}.toast{position:fixed;z-index:20;bottom:22px;left:50%;transform:translate(-50%,20px);opacity:0;pointer-events:none;border:1px solid #ffcf7250;background:#19192b;padding:10px 16px;border-radius:10px;color:#f5d992;font-size:11px;box-shadow:0 10px 35px #0008;transition:.2s;white-space:nowrap}.toast.show{opacity:1;transform:translate(-50%,0)}
@media(max-width:680px){.app-shell{padding:0 16px}.topbar{height:68px}.top-note{font-size:8px;letter-spacing:1px;gap:6px}.brand-name{font-size:12px}.brand-mark{width:28px;height:28px}.wallet{padding:6px 9px;min-width:auto;gap:6px}.wallet-icon{font-size:18px}.wallet small{font-size:7px}.wallet strong{font-size:15px}.wallet-coin{display:none}.intro{padding-top:23px}.intro h1{font-size:34px}.machine-wrap{width:100%}.cabinet{padding:8px;border-radius:16px}.cabinet-inner{padding:7px 10px 9px}.marquee{height:34px;margin-bottom:6px}.marquee-title{font-size:16px;letter-spacing:3.5px}.marquee-star{font-size:14px}.reel-frame{padding:6px}.reels{gap:5px}.reel{height:clamp(142px,34vw,192px)}.symbol{font-size:clamp(27px,7vw,39px)}.controls{padding:8px 3px 4px;grid-template-columns:.85fr 1.4fr .85fr;min-height:86px}.bet-stepper{gap:7px}.bet-stepper button{width:23px;height:23px}.bet-stepper strong{font-size:17px}.spin-zone{gap:7px}.spin-button{width:88px;height:67px}.auto-button{width:40px;height:39px;padding:0;justify-content:center;font-size:0}.auto-icon{font-size:16px}.auto-count{font-size:8px}.win-display strong{font-size:21px}.control-label{font-size:7px;letter-spacing:1.1px}.bet-caption,.win-caption{font-size:6px;letter-spacing:.7px}.machine-foot{gap:8px;letter-spacing:1.3px;font-size:7px}.info-row{grid-template-columns:1fr;gap:8px}.info-card{min-height:62px;padding:10px 12px}.info-card p{font-size:9px}.responsible-note{font-size:6px;letter-spacing:.7px;margin:12px 0}footer{height:36px}}
@media(max-width:390px){.app-shell{padding:0 10px}.top-note{font-size:0;gap:0}.top-note i{font-size:9px}.top-note .live-dot{margin-right:5px}.brand-name{font-size:11px;letter-spacing:.7px}.wallet{padding:6px}.marquee-title{font-size:14px;letter-spacing:2px}.reel{height:138px}.machine-foot{font-size:6px}.controls{grid-template-columns:.8fr 1.5fr .8fr}.spin-button{width:78px}.bet-stepper{gap:5px}.bet-stepper button{width:21px;height:21px}.bet-stepper strong{font-size:15px}}
@media(prefers-reduced-motion:reduce){*,*:before,*:after{animation-duration:.01ms!important;animation-iteration-count:1!important;scroll-behavior:auto!important;transition-duration:.01ms!important}}

